def transform(grid):
    h,w=len(grid),len(grid[0])
    colors=set(sum(grid,[]))-{0}
    boxes={}
    counts={}
    for c in colors:
        pts=[(r,k) for r in range(h) for k in range(w) if grid[r][k]==c]
        boxes[c]=(min(r for r,k in pts),max(r for r,k in pts),min(k for r,k in pts),max(k for r,k in pts))
        counts[c]=len(pts)
    if not colors:return [r[:] for r in grid]
    solid=[c for c in colors if (boxes[c][1]-boxes[c][0]+1)*(boxes[c][3]-boxes[c][2]+1)==counts[c]]
    front=5 if 5 in solid else min(solid or colors,key=lambda c:counts[c])
    out=[r[:] for r in grid]
    for r in range(h):
        for k in range(w):
            if grid[r][k]==front:
                out[r][k]=0
                for c,(a,b,x,y) in boxes.items():
                    if c!=front and a<=r<=b and x<=k<=y:out[r][k]=c
    for r in range(h):
        for k in range(1,w):
            if grid[r][k]==front:out[r][k-1]=front
    return out

